package de.kai.arbeitszeitgeofence.domain
import org.junit.*
import java.time.*
class WorkSessionManagerTest { @Test fun duplicateEnterDoesNotCreateSecondStart(){ val first=WorkSessionManager.startWork(WorkSessionManager.initialState(),Instant.parse("2026-07-24T06:00:00Z"),true); val second=WorkSessionManager.startWork(first,Instant.parse("2026-07-24T06:05:00Z"),true); Assert.assertEquals(first.activeStartEpochMillis,second.activeStartEpochMillis); Assert.assertTrue(second.isTracking) } @Test fun exitStopsCurrentBlock(){ val started=WorkSessionManager.startWork(WorkSessionManager.initialState(),Instant.parse("2026-07-24T06:00:00Z"),true); val (state,entry)=WorkSessionManager.stopWork(started,Instant.parse("2026-07-24T10:00:00Z"),LocalDate.parse("2026-07-24"),TrackingSource.Geofence,"Arbeitsbereich verlassen"); Assert.assertFalse(state.isTracking); Assert.assertNotNull(entry); Assert.assertEquals("Geofence",entry!!.source) } @Test fun exitWithoutActiveWorkDoesNotCreateEntry(){ val (state,entry)=WorkSessionManager.stopWork(WorkSessionManager.initialState(),Instant.parse("2026-07-24T10:00:00Z"),LocalDate.parse("2026-07-24"),TrackingSource.Geofence,"Exit ohne Start"); Assert.assertFalse(state.isTracking); Assert.assertNull(entry) } }
